import hashlib
import os
import time

# 生成彩虹表
def generate_rainbow_table(length, hash_function):
    rainbow_table = {}
    for i in range(2**length):
        password = str(i).zfill(length)
        hash_value = hash_function(password)
        rainbow_table[hash_value] = password
    return rainbow_table

# 使用彩虹表进行密码破解
def rainbow_table_attack(hash_value, rainbow_table):
    return rainbow_table.get(hash_value, None)

